import asyncio
from typing import Any, Dict

import pytest

from subject import (
    ServiceConsumerLagObserver,
    _coerce_offset,
    _require_topic_partition,
    ModelConsumerGroupLag,
    ModelTopicPartitionOffset,
)


class _FakeTopicPartition:
    def __init__(self, topic: str, partition: int) -> None:
        self.topic = topic
        self.partition = partition

    def __hash__(self) -> int:
        return hash((self.topic, self.partition))

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, _FakeTopicPartition):
            return NotImplemented
        return self.topic == other.topic and self.partition == other.partition

    def __repr__(self) -> str:
        return f"TopicPartition({self.topic!r}, {self.partition})"


class _FakeOffsetAndMetadata:
    def __init__(self, offset: int) -> None:
        self.offset = offset


class _FakeOffsetResponse:
    def __init__(self, offset: int) -> None:
        self.offset = offset


class _FakeAdmin:
    def __init__(
        self,
        committed: Dict[_FakeTopicPartition, _FakeOffsetAndMetadata] | None = None,
        end_offsets: Dict[_FakeTopicPartition, _FakeOffsetResponse] | None = None,
    ) -> None:
        self._committed = committed or {}
        self._end_offsets = end_offsets or {}

    async def list_consumer_group_offsets(
        self, group_id: str
    ) -> Dict[_FakeTopicPartition, _FakeOffsetAndMetadata]:
        return self._committed

    async def list_offsets(
        self, request: Dict[_FakeTopicPartition, int]
    ) -> Dict[_FakeTopicPartition, _FakeOffsetResponse]:
        # request keys are the same TopicPartition objects we stored
        result: Dict[_FakeTopicPartition, _FakeOffsetResponse] = {}
        for tp in request:
            if tp in self._end_offsets:
                result[tp] = self._end_offsets[tp]
        return result


def _run_async(coro):
    return asyncio.run(coro)


@pytest.mark.unit
def test_observe_empty_group_id_raises():
    admin = _FakeAdmin()
    observer = ServiceConsumerLagObserver(admin)
    with pytest.raises(ValueError, match="group_id must be a non-empty consumer group id"):
        _run_async(observer.observe(""))


@pytest.mark.unit
def test_observe_no_committed_offsets_returns_empty_lag():
    admin = _FakeAdmin(committed={})
    observer = ServiceConsumerLagObserver(admin)
    lag = _run_async(observer.observe("group-1"))
    assert isinstance(lag, ModelConsumerGroupLag)
    assert lag.group_id == "group-1"
    assert lag.partition_offsets == ()


@pytest.mark.unit
def test_observe_computes_lag_correctly():
    tp1 = _FakeTopicPartition("topic-a", 0)
    tp2 = _FakeTopicPartition("topic-a", 1)
    tp3 = _FakeTopicPartition("topic-b", 0)

    committed = {
        tp1: _FakeOffsetAndMetadata(10),
        tp2: _FakeOffsetAndMetadata(5),
        tp3: _FakeOffsetAndMetadata(0),
    }
    end_offsets = {
        tp1: _FakeOffsetResponse(15),
        tp2: _FakeOffsetResponse(5),
        tp3: _FakeOffsetResponse(100),
    }
    admin = _FakeAdmin(committed=committed, end_offsets=end_offsets)
    observer = ServiceConsumerLagObserver(admin)
    lag = _run_async(observer.observe("group-2"))

    assert lag.group_id == "group-2"
    assert len(lag.partition_offsets) == 3
    # sorted by (topic, partition)
    expected = [
        ModelTopicPartitionOffset(topic="topic-a", partition=0, committed_offset=10, log_end_offset=15),
        ModelTopicPartitionOffset(topic="topic-a", partition=1, committed_offset=5, log_end_offset=5),
        ModelTopicPartitionOffset(topic="topic-b", partition=0, committed_offset=0, log_end_offset=100),
    ]
    assert list(lag.partition_offsets) == expected


@pytest.mark.unit
def test_observe_missing_end_offset_raises():
    tp = _FakeTopicPartition("topic-x", 0)
    admin = _FakeAdmin(committed={tp: _FakeOffsetAndMetadata(10)}, end_offsets={})
    observer = ServiceConsumerLagObserver(admin)
    with pytest.raises(ValueError, match="no log-end offset returned for partition"):
        _run_async(observer.observe("group-3"))


